# name: repdigit_set_repdigit_target_lift
# description: In sets containing >=2 repdigit examples (11,22,...,99), yes rate on non-example repdigit targets minus yes rate on other non-example targets; observed > null means the model lacks a "repeated digits" concept people use.
def test_statistic(df):
    rep = {11, 22, 33, 44, 55, 66, 77, 88, 99}
    sets = df["number_set"].astype(str)
    t = df["target"].astype(int).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    feat = {}
    for s in sets.unique():
        ex = [int(v) for v in s.split(",")]
        feat[s] = (sum(v in rep for v in ex) >= 2, ex)
    ok = sets.map(lambda s: feat[s][0]).to_numpy(bool)
    isex = np.array([ti in feat[s][1] for s, ti in zip(sets, t)])
    base = ok & ~isex
    isrep = np.isin(t, list(rep))
    a = base & isrep; b = base & ~isrep
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())

# name: final_digit_with_outlier_yes
# description: In sets of >=3 examples where all but exactly one share a final digit, yes rate on non-example targets ending in that majority digit; observed > null means people tolerate an off-rule example more than the model's fixed 0.1 noise allows (observed < null: less).
def test_statistic(df):
    sets = df["number_set"].astype(str)
    t = df["target"].astype(int).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    feat = {}
    for s in sets.unique():
        ex = [int(v) for v in s.split(",")]
        d = -1
        if len(ex) >= 3:
            ds = [v % 10 for v in ex]
            for k in set(ds):
                if ds.count(k) == len(ex) - 1:
                    d = k
        feat[s] = (d, ex)
    dig = sets.map(lambda s: feat[s][0]).to_numpy(int)
    isex = np.array([ti in feat[s][1] for s, ti in zip(sets, t)])
    m = (dig >= 0) & ~isex & (t % 10 == dig)
    if m.sum() == 0:
        return 0.0
    return float(y[m].mean())

# name: prime_set_odd_composite_yes
# description: In sets of >=2 examples that are all prime, yes rate on odd composite (non-prime, >1) targets; observed > null means the model's prime-over-odd preference suppresses "odd" readings too strongly after prime sets (observed < null: not strongly enough).
def test_statistic(df):
    def isp(n):
        return n > 1 and all(n % k for k in range(2, int(n ** 0.5) + 1))
    sets = df["number_set"].astype(str)
    t = df["target"].astype(int).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    feat = {s: (lambda ex: len(ex) >= 2 and all(isp(v) for v in ex))([int(v) for v in s.split(",")]) for s in sets.unique()}
    ok = sets.map(feat).to_numpy(bool)
    primes = np.array([isp(n) for n in range(101)])
    m = ok & (t % 2 == 1) & (t > 1) & ~primes[t]
    if m.sum() == 0:
        return 0.0
    return float(y[m].mean())
